//! Cross-language vectors generated by packages/protocol/test/vectors.ts.
use vp_agent::crypto::*;
use vp_agent::util::{b64u, from_b64u};

#[test]
fn matches_typescript_vectors() {
    let v: serde_json::Value = serde_json::from_str(include_str!("vectors.json")).unwrap();
    let fill = |n: usize, b: u8| vec![b; n];
    let agent_pub = fill(65, 4);
    let server_eph = fill(65, 5);
    let server_nonce = fill(32, 6);
    let c = commit(&server_eph, &server_nonce);
    assert_eq!(b64u(&c), v["commit"]);
    let t = transcript(&TranscriptInput {
        agent_id: "AAAAAAAAAAAAAAAAAAAAAA",
        agent_pub: &agent_pub,
        commit: &c,
        mode: "pair",
        client_eph: &fill(65, 7),
        client_nonce: &fill(32, 8),
        device_id: "BBBBBBBBBBBBBBBBBBBBBB",
        device_pub: &fill(65, 9),
        device_name: "Bryan's iPad ✎",
        device_kind: "ipad",
        server_eph: &server_eph,
        server_nonce: &server_nonce,
    });
    assert_eq!(b64u(&t), v["transcript"]);
    let keys = derive_session_keys(&fill(32, 42), t);
    assert_eq!(b64u(&keys.c2s), v["c2s"]);
    assert_eq!(b64u(&keys.s2c), v["s2c"]);
    assert_eq!(keys.sas, v["sas"]);
    assert_eq!(keys.session_id, v["sessionId"]);
    assert_eq!(b64u(&next_epoch_key(&keys.c2s)), v["rekey"]);
    assert_eq!(b64u(&pair_proof_mac("123456", &t)), v["pairMac"]);

    let frame: EncryptedFrame = serde_json::from_value(v["frame"].clone()).unwrap();
    let mut server = SecureChannel::new(&keys, Role::Server);
    let message = server.open(&frame).unwrap().unwrap();
    assert_eq!(message, serde_json::json!({"t": "ping", "n": 1}));
    let _ = from_b64u("", None);
}
